/**
 * OUVRIR UN TERMINAL
 *
 * Utilisation :
 * 1. Glissez cette macro du Compendium vers votre barre de macros.
 * 2. Ouvrez sa configuration.
 * 3. Remplacez TERMINAL_UUID par l’UUID du Journal Terminal.
 * 4. PAGE_UUID est facultatif; laissez-le vide pour ouvrir la page d’accueil.
 *
 * Pour copier un UUID dans Foundry : clic droit sur le Journal ou la page,
 * puis « Copier l’UUID » selon votre interface.
 */

// ── CONFIGURATION À MODIFIER ──────────────────────────────────
const TERMINAL_UUID = "JournalEntry.REMPLACEZ_MOI";
const PAGE_UUID = ""; // Exemple : JournalEntry.xxx.JournalEntryPage.yyy
// ──────────────────────────────────────────────────────────────

const api = game.modules.get("retro-crt-terminal")?.api;
if (!api) return ui.notifications.error("Retro CRT Terminal n’est pas actif.");
if (!TERMINAL_UUID || TERMINAL_UUID.includes("REMPLACEZ_MOI")) {
  return ui.notifications.warn("Modifiez TERMINAL_UUID dans la configuration de la macro.");
}

await api.open(TERMINAL_UUID, PAGE_UUID ? { page: PAGE_UUID } : {});
